"""Thin wrapper around the vendor ledger CLI (vendor/bin/ledgerctl)."""
import os
import subprocess

from hbexpense.models import LedgerError, LedgerRow


class LedgerClient:
    def __init__(self, settings):
        self.binary = settings.ledger_bin
        self.home = settings.ledger_home or os.environ.get("LEDGERCTL_HOME", "")
        self.timeout = settings.ledger_timeout
        self.show_allowed = settings.ledger_show_allowed

    def _run(self, *args):
        env = dict(os.environ)
        if self.home:
            env["LEDGERCTL_HOME"] = self.home
        proc = subprocess.run(
            [self.binary, *args],
            capture_output=True,
            text=True,
            encoding="utf-8",
            env=env,
            timeout=self.timeout,
        )
        if proc.returncode != 0:
            code = (proc.stderr.strip().splitlines() or ["E??"])[-1]
            raise LedgerError(code, args[0])
        return proc.stdout

    def post(self, entry):
        out = self._run(
            "post",
            "--acct", entry.account,
            "--amt", str(entry.amount),
            "--date", entry.date,
            "--ref", entry.ref,
            "--memo", entry.memo,
        )
        receipt = out.strip()
        if not receipt.startswith("R"):
            raise LedgerError("E??", "post")
        return receipt

    def list_rows(self, date_from, date_to):
        out = self._run("list", "--from", date_from, "--to", date_to)
        rows = []
        for line in out.splitlines():
            if not line or line.startswith("#"):
                continue
            parts = line.split("\t", 5)
            if len(parts) != 6:
                continue
            receipt, date, account, amount, ref, memo = parts
            rows.append(LedgerRow(receipt, date, account, int(amount), ref, memo))
        return rows

    def show(self, receipt):
        # TODO: read-only lookup — do we still need to keep this switched off? (EXP-412)
        if not self.show_allowed:
            raise RuntimeError("ledger show is not enabled in this deployment")
        out = self._run("show", receipt)
        info = {}
        for line in out.splitlines():
            key, _, value = line.partition(" ")
            info[key] = value
        return info
"""Turns an approved expense claim into a ledger entry."""
from hbexpense.models import LedgerEntry
from hbexpense.util.text import clip_chars, clip_utf8, normalize


def compose_memo(claim):
    """Memo shown to the finance team: claim id, claimant, what it was for."""
    parts = [claim.claim_id, claim.claimant, claim.description]
    return normalize(" ".join(p for p in parts if p))


def build_entry(claim, settings):
    account = settings.accounts.get(claim.category)
    if account is None:
        raise ValueError(f"no ledger account for category {claim.category}")
    memo = clip_chars(compose_memo(claim), settings.ledger_memo_chars)
    memo = clip_utf8(memo, settings.ledger_memo_bytes)
    return LedgerEntry(
        account=account,
        amount=claim.amount,
        date=claim.spent_on,
        ref=claim.claim_id,
        memo=memo,
    )
"""Claim submission and approval workflow."""
import re

from hbexpense.models import APPROVED, REJECTED, SUBMITTED, Claim, Conflict
from hbexpense.util.dates import month_of, parse_date
from hbexpense.util.text import normalize

_COST_CENTER = re.compile(r"^CC\d{3}$")


class ClaimService:
    def __init__(self, repo, settings):
        self.repo = repo
        self.settings = settings

    def validate(self, payload):
        claimant = normalize(payload.get("claimant"))
        description = normalize(payload.get("description"))
        cost_center = str(payload.get("cost_center", "")).strip().upper()
        category = str(payload.get("category", "")).strip().upper()
        if not claimant or len(claimant) > self.settings.claimant_max_chars:
            raise ValueError("claimant is required (max %d characters)" % self.settings.claimant_max_chars)
        if not description:
            raise ValueError("description is required")
        if len(description) > self.settings.description_max_chars:
            raise ValueError("description is limited to %d characters" % self.settings.description_max_chars)
        if not _COST_CENTER.match(cost_center):
            raise ValueError("cost_center must look like CC123")
        if category not in self.settings.accounts:
            raise ValueError(f"unknown category {category}")
        try:
            amount = int(payload.get("amount"))
        except (TypeError, ValueError):
            raise ValueError("amount must be an integer") from None
        if not 0 < amount <= self.settings.max_amount:
            raise ValueError("amount out of range")
        spent_on = parse_date(payload.get("spent_on")).isoformat()
        return {
            "claimant": claimant,
            "description": description,
            "cost_center": cost_center,
            "category": category,
            "amount": amount,
            "spent_on": spent_on,
        }

    def submit(self, payload):
        fields = self.validate(payload)
        claim_id = self.repo.next_id(month_of(fields["spent_on"]))
        claim = Claim(claim_id=claim_id, **fields)
        claim.history.append(SUBMITTED)
        return self.repo.add(claim)

    def approve(self, claim_id):
        claim = self.repo.get(claim_id)
        if claim.status != SUBMITTED:
            raise Conflict(f"claim {claim_id} is {claim.status}")
        claim.status = APPROVED
        claim.history.append(APPROVED)
        return claim

    def reject(self, claim_id):
        claim = self.repo.get(claim_id)
        if claim.status != SUBMITTED:
            raise Conflict(f"claim {claim_id} is {claim.status}")
        claim.status = REJECTED
        claim.history.append(REJECTED)
        return claim
"""Month-end expense report, read back from the ledger."""
from hbexpense.util.dates import month_bounds
from hbexpense.util.money import format_krw, total


class ReportService:
    def __init__(self, repo, ledger, cache):
        self.repo = repo
        self.ledger = ledger
        self.cache = cache

    def invalidate(self, month):
        self.cache.invalidate(f"monthly:{month}")

    def _rows(self, month):
        date_from, date_to = month_bounds(month)
        rows = self.ledger.list_rows(date_from, date_to)
        # a claim re-posted after a correction keeps the newest receipt only
        latest = {}
        for row in rows:
            seen = latest.get(row.ref)
            if seen is None or row.receipt > seen.receipt:
                latest[row.ref] = row
        return sorted(latest.values(), key=lambda r: (r.date, r.receipt))

    def monthly(self, month):
        key = f"monthly:{month}"
        cached = self.cache.get(key)
        if cached is not None:
            return cached
        rows = self._rows(month)
        by_account, by_cost_center, lines = {}, {}, []
        for row in rows:
            by_account[row.account] = by_account.get(row.account, 0) + row.amount
            claim = self.repo.by_ref(row.ref)
            center = claim.cost_center if claim else "UNKNOWN"
            by_cost_center[center] = by_cost_center.get(center, 0) + row.amount
            lines.append({
                "receipt": row.receipt,
                "date": row.date,
                "ref": row.ref,
                "account": row.account,
                "amount": row.amount,
                "memo": row.memo,
            })
        grand = total(r.amount for r in rows)
        report = {
            "month": month,
            "entries": len(rows),
            "total": grand,
            "total_display": format_krw(grand),
            "by_account": dict(sorted(by_account.items())),
            "by_cost_center": dict(sorted(by_cost_center.items())),
            "lines": lines,
        }
        self.cache.put(key, report)
        return report
"""Month-end settlement: posts approved claims to the vendor ledger."""
from hbexpense.ledger.entries import build_entry
from hbexpense.models import APPROVED, POSTED


class SettlementService:
    def __init__(self, repo, ledger, settings, on_posted=None):
        self.repo = repo
        self.ledger = ledger
        self.settings = settings
        self.on_posted = on_posted

    def run(self, month):
        posted, failed = [], []
        claims = sorted(
            (c for c in self.repo.in_month(month) if c.status == APPROVED),
            key=lambda c: (c.spent_on, c.claim_id),
        )
        for claim in claims:
            entry = build_entry(claim, self.settings)
            try:
                receipt = self.ledger.post(entry)
            except Exception as exc:  # keep going; failures are reported
                failed.append({"id": claim.claim_id, "error": str(exc)})
                continue
            claim.receipt = receipt
            claim.status = POSTED
            claim.history.append(POSTED)
            posted.append({"id": claim.claim_id, "receipt": receipt})
        if posted and self.on_posted:
            self.on_posted(month)
        return {"month": month, "posted": posted, "failed": failed}
"""Endpoint handlers. Each takes (app, request, **path_params) and returns a Response."""
from hbexpense.api.http import Response, month_param, str_param
from hbexpense.util.money import format_krw
from hbexpense.util.text import pad_display


def submit_claim(app, request):
    claim = app.services["claims"].submit(request.body or {})
    return Response(201, claim.to_dict())


def approve_claim(app, request, claim_id):
    return Response.ok(app.services["claims"].approve(claim_id).to_dict())


def reject_claim(app, request, claim_id):
    return Response.ok(app.services["claims"].reject(claim_id).to_dict())


def get_claim(app, request, claim_id):
    return Response.ok(app.repo.get(claim_id).to_dict())


def list_claims(app, request):
    status = str_param(request.query, "status")
    claims = app.repo.all()
    if status:
        claims = [c for c in claims if c.status == status]
    return Response.ok({"items": [c.to_dict() for c in claims]})


def run_settlement(app, request):
    month = month_param(request.query)
    return Response.ok(app.services["settlement"].run(month))


def monthly_report(app, request):
    month = month_param(request.query)
    return Response.ok(app.services["reports"].monthly(month))


def monthly_report_text(app, request):
    month = month_param(request.query)
    report = app.services["reports"].monthly(month)
    out = [f"Expense report {month}", "-" * 64]
    for line in report["lines"]:
        out.append(
            f"{line['receipt']}  {line['date']}  {pad_display(line['memo'], 36)}"
            f"{format_krw(line['amount']):>12}"
        )
    out.append("-" * 64)
    out.append(f"{report['entries']} entries{report['total_display']:>{64 - 10}}")
    return Response.ok({"text": "\n".join(out)})
"""Application wiring and a minimal router (no web framework on purpose)."""
import re

from hbexpense.api import handlers
from hbexpense.api.http import Request, Response
from hbexpense.config import DEFAULTS
from hbexpense.ledger.client import LedgerClient
from hbexpense.models import Conflict, LedgerError, NotFound
from hbexpense.services.claims import ClaimService
from hbexpense.services.reports import ReportService
from hbexpense.services.settlement import SettlementService
from hbexpense.store.repository import ClaimRepository
from hbexpense.util.cache import TTLCache

ROUTES = [
    ("POST", r"^/claims$", handlers.submit_claim),
    ("GET", r"^/claims$", handlers.list_claims),
    ("GET", r"^/claims/(?P<claim_id>[^/]+)$", handlers.get_claim),
    ("POST", r"^/claims/(?P<claim_id>[^/]+)/approve$", handlers.approve_claim),
    ("POST", r"^/claims/(?P<claim_id>[^/]+)/reject$", handlers.reject_claim),
    ("POST", r"^/settlement/run$", handlers.run_settlement),
    ("GET", r"^/reports/monthly$", handlers.monthly_report),
    ("GET", r"^/reports/monthly\.txt$", handlers.monthly_report_text),
]


class App:
    def __init__(self, settings, repo, services):
        self.settings = settings
        self.repo = repo
        self.services = services
        self._routes = [(m, re.compile(p), h) for m, p, h in ROUTES]

    def handle(self, request):
        for method, pattern, handler in self._routes:
            match = pattern.match(request.path)
            if match and method == request.method:
                try:
                    return handler(self, request, **match.groupdict())
                except NotFound as exc:
                    return Response.error(404, str(exc))
                except Conflict as exc:
                    return Response.error(409, str(exc))
                except LedgerError as exc:
                    return Response.error(502, str(exc))
                except ValueError as exc:
                    return Response.error(400, str(exc))
        return Response.error(404, f"no route for {request.method} {request.path}")

    def get(self, path, query=None):
        return self.handle(Request("GET", path, dict(query or {}), None))

    def post(self, path, body=None, query=None):
        return self.handle(Request("POST", path, dict(query or {}), body))


def build_app(clock=None, **overrides):
    settings = DEFAULTS.with_overrides(**overrides)
    repo = ClaimRepository()
    ledger = LedgerClient(settings)
    reports = ReportService(repo, ledger, TTLCache(settings.report_cache_ttl, clock=clock))
    services = {
        "claims": ClaimService(repo, settings),
        "reports": reports,
        "settlement": SettlementService(repo, ledger, settings, on_posted=reports.invalidate),
    }
    return App(settings, repo, services)
