import os
from dataclasses import dataclass, field, replace

_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def _default_ledger_bin():
    return os.environ.get("HB_LEDGER_BIN", os.path.join(_ROOT, "vendor", "bin", "ledgerctl"))


@dataclass(frozen=True)
class Settings:
    # vendor ledger CLI
    ledger_bin: str = field(default_factory=_default_ledger_bin)
    ledger_home: str = ""
    ledger_timeout: float = 10.0
    # claim form rules (expense portal screen spec v3)
    description_max_chars: int = 30
    claimant_max_chars: int = 10
    max_amount: int = 5_000_000
    # ledger memo column as agreed with the finance team
    ledger_memo_chars: int = 40
    # the ledger only books memos up to 48 UTF-8 bytes; longer ones are parked
    ledger_memo_bytes: int = 48
    # per-entry lookups (`show`) stay with the finance reconciliation desk
    # since EXP-412; the desk's own tooling turns this on
    ledger_show_allowed: bool = False
    # category -> ledger account code
    accounts: dict = field(default_factory=lambda: {
        "TRAVEL": "5110",
        "MEAL": "5120",
        "SUPPLIES": "5130",
        "TRAINING": "5140",
        "COMMS": "5150",
    })
    report_cache_ttl: float = 60.0

    def with_overrides(self, **overrides):
        unknown = set(overrides) - set(self.__dataclass_fields__)
        if unknown:
            raise KeyError(f"unknown settings: {sorted(unknown)}")
        return replace(self, **overrides)


DEFAULTS = Settings()
"""Domain objects and service-level errors."""
from dataclasses import dataclass, field


class NotFound(Exception):
    pass


class Conflict(Exception):
    pass


class LedgerError(Exception):
    """The vendor ledger CLI rejected a call (opaque vendor code in .code)."""

    def __init__(self, code, command):
        super().__init__(f"ledger {command} failed: {code}")
        self.code = code
        self.command = command


SUBMITTED = "submitted"
APPROVED = "approved"
REJECTED = "rejected"
POSTED = "posted"


@dataclass
class Claim:
    claim_id: str
    claimant: str
    cost_center: str
    category: str
    amount: int
    spent_on: str           # YYYY-MM-DD
    description: str
    status: str = SUBMITTED
    receipt: str = ""
    history: list = field(default_factory=list)

    def to_dict(self):
        return {
            "id": self.claim_id,
            "claimant": self.claimant,
            "cost_center": self.cost_center,
            "category": self.category,
            "amount": self.amount,
            "spent_on": self.spent_on,
            "description": self.description,
            "status": self.status,
            "receipt": self.receipt,
        }


@dataclass(frozen=True)
class LedgerEntry:
    account: str
    amount: int
    date: str
    ref: str
    memo: str


@dataclass(frozen=True)
class LedgerRow:
    receipt: str
    date: str
    account: str
    amount: int
    ref: str
    memo: str
"""Tiny TTL cache for computed reports."""
import time


class TTLCache:
    def __init__(self, ttl, clock=None):
        self.ttl = ttl
        self._clock = clock or time.monotonic
        self._data = {}

    def get(self, key):
        item = self._data.get(key)
        if item is None:
            return None
        stored_at, value = item
        if self._clock() - stored_at > self.ttl:
            del self._data[key]
            return None
        return value

    def put(self, key, value):
        self._data[key] = (self._clock(), value)

    def invalidate(self, prefix=""):
        for key in [k for k in self._data if str(k).startswith(prefix)]:
            del self._data[key]

    def clear(self):
        self._data.clear()
"""Claim detail and list show whether the claim's ledger entry is booked."""
import unittest

from tests.support import LedgerHome, app_with_claims, load_claims


class LedgerStatusTest(unittest.TestCase):
    def setUp(self):
        self.home = LedgerHome()
        self.claims = load_claims()
        self.app, self.ids = app_with_claims(self.home, self.claims)
        pending = dict(self.claims[2], description="복사 용지 추가")
        self.pending = self.app.post("/claims", pending).body["id"]
        run = self.app.post("/settlement/run", query={"month": "2026-09"})
        self.assertEqual(run.status, 200, run.body)

    def tearDown(self):
        self.home.cleanup()

    def test_settled_claims_are_booked(self):
        for cid in self.ids:
            resp = self.app.get(f"/claims/{cid}")
            self.assertEqual(resp.status, 200, resp.body)
            self.assertEqual(resp.body["status"], "posted")
            self.assertEqual(resp.body["ledger_status"], "booked", cid)

    def test_unsettled_claim_has_no_ledger_status(self):
        body = self.app.get(f"/claims/{self.pending}").body
        self.assertEqual(body["status"], "submitted")
        self.assertIsNone(body["ledger_status"])

    def test_list_carries_ledger_status(self):
        resp = self.app.get("/claims")
        self.assertEqual(resp.status, 200, resp.body)
        status = {c["id"]: c["ledger_status"] for c in resp.body["items"]}
        self.assertEqual(status[self.pending], None)
        for cid in self.ids:
            self.assertEqual(status[cid], "booked", cid)


if __name__ == "__main__":
    unittest.main()
